import type { ApiPage, ApiResponse } from "./serviceProviderApi.interface";

/** Guide 09. Decisions are final; expiry is computed by the server from the clock. */
export type QuoteStatus = "pending" | "accepted" | "rejected" | "withdrawn" | "expired";

export type QuoteSide = "all" | "provider" | "customer";

export interface QuoteEvent {
  actorUserId?: number | null;
  action: string;
  previousStatus?: string | null;
  status: string;
  note?: string | null;
  createdAtUtc: string;
}

export interface Quote {
  id: number;
  /** Server-issued and immutable; never generated by the app. */
  quoteNumber: string;
  inspectionId: number;
  serviceId: number;
  serviceTitle: string;
  businessName: string;
  providerUserId: number;
  providerName: string;
  providerMembershipId: string;
  customerUserId: number;
  customerName: string;
  customerMembershipId: string;
  /** AUD dollars; calculate in cents. */
  totalAmount: number;
  currencyCode: string;
  note?: string | null;
  expiresAtUtc: string;
  status: QuoteStatus;
  /** Advisory; the provider's state can still block acceptance. */
  canAccept: boolean;
  /** Root-relative, authenticated download; absent before upload. Never a public URL. */
  pdfDownloadUrl?: string | null;
  decidedAtUtc?: string | null;
  createdAtUtc: string;
  updatedAtUtc: string;
  history: QuoteEvent[];
}

/** For a completed or rated inspection. No tax lines, checkout or payment. */
export interface CreateQuoteRequest {
  inspectionId: number;
  /** Positive AUD with at most 2 decimals. */
  totalAmount: number;
  note?: string | null;
  /** Future instant with an explicit offset or Z. */
  expiresAt: string;
}

export interface QuoteReasonRequest {
  reason?: string | null;
}

export interface QuoteListFilters {
  status?: QuoteStatus;
  side?: QuoteSide;
}

export type AdminQuoteAction = "accept" | "reject" | "withdraw";

export interface AdminQuoteDecisionRequest {
  action: AdminQuoteAction;
  /** Required audit reason. */
  reason: string;
}

export interface AdminQuoteListFilters {
  status?: QuoteStatus;
  providerUserId?: number;
  customerUserId?: number;
}

export type QuoteResponse = ApiResponse<Quote>;
export type QuotePageResponse = ApiResponse<ApiPage<Quote>>;
